**3. `game.js`** — Canvas game loop: player dot, WASD/Arrow input, collectibles, score, R restart.

ADMISSIBLE_STRUCTURED_OPERATION:
```json
{"operation": "write_file", "path": "game.js", "content": "(function () {
  "use strict";

  var canvas = document.getElementById("game");
  var scoreEl = document.getElementById("score");
  var ctx = canvas.getContext("2d");

  var WIDTH = canvas.width;
  var HEIGHT = canvas.height;
  var PLAYER_RADIUS = 8;
  var PLAYER_SPEED = 3.5;
  var COLLECTIBLE_RADIUS = 5;
  var COLLECTIBLE_COUNT = 8;
  var COLLECTIBLE_COLORS = ["#ff6b6b", "#ffe066", "#69db7c", "#74c0fc", "#da77f2", "#ffa94d"];

  var keys = {};
  var player = { x: WIDTH / 2, y: HEIGHT / 2, radius: PLAYER_RADIUS };
  var collectibles = [];
  var score = 0;

  function rand(min, max) {
    return min + Math.random() * (max - min);
  }

  function spawnCollectible() {
    var margin = COLLECTIBLE_RADIUS + 4;
    return {
      x: rand(margin, WIDTH - margin),
      y: rand(margin, HEIGHT - margin),
      radius: COLLECTIBLE_RADIUS,
      color: COLLECTIBLE_COLORS[Math.floor(Math.random() * COLLECTIBLE_COLORS.length)]
    };
  }

  function initCollectibles() {
    collectibles = [];
    for (var i = 0; i < COLLECTIBLE_COUNT; i++) {
      collectibles.push(spawnCollectible());
    }
  }

  function resetGame() {
    score = 0;
    scoreEl.textContent = "0";
    player.x = WIDTH / 2;
    player.y = HEIGHT / 2;
    initCollectibles();
  }

  function clampPlayer() {
    var r = player.radius;
    if (player.x < r) player.x = r;
    if (player.x > WIDTH - r) player.x = WIDTH - r;
    if (player.y < r) player.y = r;
    if (player.y > HEIGHT - r) player.y = HEIGHT - r;
  }

  function updatePlayer() {
    var dx = 0;
    var dy = 0;
    if (keys["ArrowLeft"] || keys["a"] || keys["A"]) dx -= 1;
    if (keys["ArrowRight"] || keys["d"] || keys["D"]) dx += 1;
    if (keys["ArrowUp"] || keys["w"] || keys["W"]) dy -= 1;
    if (keys["ArrowDown"] || keys["s"] || keys["S"]) dy += 1;

    if (dx !== 0 || dy !== 0) {
      var len = Math.sqrt(dx * dx + dy * dy);
      player.x += (dx / len) * PLAYER_SPEED;
      player.y += (dy / len) * PLAYER_SPEED;
    }
    clampPlayer();
  }

  function dist(ax, ay, bx, by) {
    var dx = bx - ax;
    var dy = by - ay;
    return Math.sqrt(dx * dx + dy * dy);
  }

  function checkCollectibles() {
    for (var i = collectibles.length - 1; i >= 0; i--) {
      var c = collectibles[i];
      if (dist(player.x, player.y, c.x, c.y) < player.radius + c.radius) {
        score += 1;
        scoreEl.textContent = String(score);
        collectibles.splice(i, 1);
        collectibles.push(spawnCollectible());
      }
    }
  }

  function drawBackground() {
    ctx.fillStyle = "#111820";
    ctx.fillRect(0, 0, WIDTH, HEIGHT);

    ctx.strokeStyle = "#1e2a38";
    ctx.lineWidth = 1;
    for (var gx = 0; gx <= WIDTH; gx += 32) {
      ctx.beginPath();
      ctx.moveTo(gx, 0);
      ctx.lineTo(gx, HEIGHT);
      ctx.stroke();
    }
    for (var gy = 0; gy <= HEIGHT; gy += 32) {
      ctx.beginPath();
      ctx.moveTo(0, gy);
      ctx.lineTo(WIDTH, gy);
      ctx.stroke();
    }
  }

  function drawPlayer() {
    ctx.beginPath();
    ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
    ctx.fillStyle = "#7cf0ff";
    ctx.fill();
    ctx.strokeStyle = "#ffffff";
    ctx.lineWidth = 2;
    ctx.stroke();
  }

  function drawCollectibles() {
    for (var i = 0; i < collectibles.length; i++) {
      var c = collectibles[i];
      ctx.beginPath();
      ctx.arc(c.x, c.y, c.radius, 0, Math.PI * 2);
      ctx.fillStyle = c.color;
      ctx.fill();
      ctx.strokeStyle = "#ffffff";
      ctx.lineWidth = 1;
      ctx.stroke();
    }
  }

  function tick() {
    updatePlayer();
    checkCollectibles();
    drawBackground();
    drawCollectibles();
    drawPlayer();
    requestAnimationFrame(tick);
  }

  window.addEventListener("keydown", function (e) {
    keys[e.key] = true;
    if (e.key === "r" || e.key === "R") {
      resetGame();
    }
    if (["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight", " "].indexOf(e.key) !== -1) {
      e.preventDefault();
    }
  });

  window.addEventListener("keyup", function (e) {
    keys[e.key] = false;
  });

  resetGame();
  requestAnimationFrame(tick);
})();
"}
```

